            border-color: rgba(138, 43, 226, 0.5);
        }

        .filter-tag.selected {
            background: linear-gradient(135deg, #8a2be2, #5a189a);
            color: white;
            border-color: #8a2be2;
        }

        /* 确认按钮 */
        .confirm-filter {
            width: 100%;
            padding: 12px;
            background: linear-gradient(135deg, #8a2be2, #ff69b4);
            color: white;
            border: none;
            border-radius: 10px;
