    <script>
        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 处理标签内容
            const tagContainers = document.querySelectorAll('.video-tags');
            tagContainers.forEach(container => {
                const tagText = container.textContent;
                const tags = tagText.split('#').filter(tag => tag.trim());
                container.innerHTML = tags.map(tag => `<span class="tag">#${tag.trim()}</span>`).join('');
            });

            // 处理热门标记
            const titles = document.querySelectorAll('.video-title');
            titles.forEach(title => {
                if (title.textContent.includes('【热门】')) {
                    title.innerHTML = title.textContent.replace('【热门】', '<span class="hot-badge">热门</span>');
                }
            });

            // 根据当前区域显示/隐藏特定筛选项
            updateZoneFilters();

            // 筛选标签点击事件
            document.querySelectorAll('.filter-tag').forEach(tag => {
                tag.addEventListener('click', function() {
                    this.classList.toggle('selected');
                });
            });
        });

        // 区域切换功能
        function switchZone(zone) {
            const buttons = document.querySelectorAll('.zone-btn');
            buttons.forEach(btn => {
                if (btn.dataset.zone === zone) {
                    btn.classList.add('active');
                } else {
                    btn.classList.remove('active');
                }
            });

            // 更新筛选项显示
            updateZoneFilters();

            // 发送切换区域的命令
            const zoneName = zone === 'adult' ? '成年女性区' : '幼女区';
            const command = `/send 切换到${zoneName} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 更新区域筛选项
        function updateZoneFilters() {
            const pageInfo = document.querySelector('.page-info');
            const currentZone = pageInfo.dataset.zone;
            const youngOnlyFilters = document.querySelectorAll('.young-only');

            if (currentZone === '幼女区') {
                youngOnlyFilters.forEach(filter => {
                    filter.style.display = 'block';
                });
                // 幼女区的修为筛选只显示部分
                const cultivationFilter = document.getElementById('cultivation-filter');
                if (cultivationFilter) {
                    cultivationFilter.innerHTML = `
                        <span class="filter-tag">凡人</span>
                        <span class="filter-tag">炼气</span>
                        <span class="filter-tag">筑基</span>
                        <span class="filter-tag">道境</span>
                    `;
                }
                // 显示诱奸标签
                const categoryType = document.getElementById('category-type');
                if (categoryType) {
                    categoryType.style.display = 'block';
                }
            } else {
                youngOnlyFilters.forEach(filter => {
                    filter.style.display = 'none';
                });
                // 成年女性区隐藏诱奸相关
                const categoryType = document.getElementById('category-type');
                if (categoryType) {
                    const filterOptions = categoryType.querySelector('.filter-options');
                    filterOptions.innerHTML = '<span class="filter-tag">迷奸</span>';
                }
            }
        }

        // 查看帖子详情
        function viewPost(element) {
            const postId = element.dataset.id;
            const title = element.querySelector('.video-title').textContent.replace(/【热门】/g, '').trim();
            const command = `/send 查看帖子：${title} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 应用筛选
        function applyFilters() {
            const selectedTags = [];
            document.querySelectorAll('.filter-tag.selected').forEach(tag => {
                selectedTags.push(tag.textContent);
            });

            if (selectedTags.length > 0) {
                const command = `/echo severity=success 正在应用筛选条件... | /send 筛选标签：${selectedTags.join('、')} | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            } else {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/echo severity=warning 请至少选择一个筛选条件`);
                }
            }
        }

        // 翻页功能
        function goToPage(page) {
            const pageInfo = document.querySelector('.page-info');
            const currentPage = parseInt(pageInfo.dataset.current);
            const totalPages = parseInt(pageInfo.dataset.total);
            let targetPage;

            if (page === 'first') {
                targetPage = 1;
            } else if (page === 'last') {
                targetPage = totalPages;
            } else if (page === 'prev') {
                targetPage = Math.max(1, currentPage - 1);
            } else if (page === 'next') {
                targetPage = Math.min(totalPages, currentPage + 1);
            } else {
                targetPage = parseInt(page);
            }

            if (targetPage !== currentPage && targetPage >= 1 && targetPage <= totalPages) {
                const command = `/send 跳转到第${targetPage}页 | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            }
        }
    </script>
