    <script>
        // 初始化页面
        document.addEventListener('DOMContentLoaded', function() {
            // 处理标签内容
            const tagContainers = document.querySelectorAll('.video-tags');
            tagContainers.forEach(container => {
                const tagText = container.textContent;
                const tags = tagText.split('#').filter(tag => tag.trim());
                container.innerHTML = tags.map(tag => `<span class="tag">#${tag.trim()}</span>`).join('');
            });

            // 处理热门标记
            const titles = document.querySelectorAll('.video-title');
            titles.forEach(title => {
                if (title.textContent.includes('【热门】')) {
                    title.innerHTML = title.textContent.replace('【热门】', '<span class="hot-badge">热门</span>');
                }
            });

            // 根据当前区域显示/隐藏特定筛选项
            updateZoneFilters();

            // 筛选标签点击事件
            document.querySelectorAll('.filter-tag').forEach(tag => {
                tag.addEventListener('click', function() {
                    this.classList.toggle('selected');
                });
            });
        });

        // 区域切换功能
        function switchZone(zone) {
            const buttons = document.querySelectorAll('.zone-btn');
            buttons.forEach(btn => {
                if (btn.dataset.zone === zone) {
                    btn.classList.add('active');
                } else {
                    btn.classList.remove('active');
                }
            });

            // 更新筛选项显示
            updateZoneFilters();

            // 发送切换区域的命令
            const zoneName = zone === 'adult' ? '成年女性区' : '幼女区';
            const command = `/send 切换到${zoneName} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 更新区域筛选项
        function updateZoneFilters() {
