                        <span class="filter-tag">炼气</span>
                        <span class="filter-tag">筑基</span>
                        <span class="filter-tag">道境</span>
                    `;
                }
                // 显示诱奸标签
                const categoryType = document.getElementById('category-type');
                if (categoryType) {
                    categoryType.style.display = 'block';
                }
            } else {
                youngOnlyFilters.forEach(filter => {
                    filter.style.display = 'none';
                });
                // 成年女性区隐藏诱奸相关
                const categoryType = document.getElementById('category-type');
                if (categoryType) {
                    const filterOptions = categoryType.querySelector('.filter-options');
                    filterOptions.innerHTML = '<span class="filter-tag">迷奸</span>';
                }
            }
        }

        // 查看帖子详情
        function viewPost(element) {
            const postId = element.dataset.id;
            const title = element.querySelector('.video-title').textContent.replace(/【热门】/g, '').trim();
            const command = `/send 查看帖子：${title} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 应用筛选
        function applyFilters() {
            const selectedTags = [];
            document.querySelectorAll('.filter-tag.selected').forEach(tag => {
                selectedTags.push(tag.textContent);
            });

            if (selectedTags.length > 0) {
                const command = `/echo severity=success 正在应用筛选条件... | /send 筛选标签：${selectedTags.join('、')} | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            } else {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/echo severity=warning 请至少选择一个筛选条件`);
                }
            }
        }

        // 翻页功能
        function goToPage(page) {
            const pageInfo = document.querySelector('.page-info');
            const currentPage = parseInt(pageInfo.dataset.current);
            const totalPages = parseInt(pageInfo.dataset.total);
            let targetPage;

            if (page === 'first') {
                targetPage = 1;
            } else if (page === 'last') {
                targetPage = totalPages;
            } else if (page === 'prev') {
                targetPage = Math.max(1, currentPage - 1);
            } else if (page === 'next') {
                targetPage = Math.min(totalPages, currentPage + 1);
            } else {
                targetPage = parseInt(page);
            }

            if (targetPage !== currentPage && targetPage >= 1 && targetPage <= totalPages) {
                const command = `/send 跳转到第${targetPage}页 | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            }
        }
    </script>
