            const liveId = element.dataset.id;
            const title = element.querySelector('.live-title').textContent.replace(/热门/g, '').trim();
            const streamer = element.querySelector('.meta-value').textContent;
            const command = `/send 进入直播间：${title} 主播：${streamer} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 确认筛选
        function confirmFilters() {
            const selectedFilters = [];
            document.querySelectorAll('.filter-item.selected').forEach(item => {
                selectedFilters.push(item.textContent);
            });

            if (selectedFilters.length > 0) {
                const command = `/echo severity=success 正在应用筛选条件，请稍候... | /send 筛选直播：${selectedFilters.join('、')} | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            } else {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/echo severity=warning 请至少选择一个筛选条件`);
                }
            }
        }

        // 翻页导航
        function navigatePage(page) {
            const pageIndicator = document.querySelector('.page-indicator');
            const currentPage = parseInt(pageIndicator.dataset.current);
            const totalPages = parseInt(pageIndicator.dataset.total);
            let targetPage;

            if (page === 'first') {
                targetPage = 1;
            } else if (page === 'last') {
                targetPage = totalPages;
            } else if (page === 'prev') {
                targetPage = Math.max(1, currentPage - 1);
            } else if (page === 'next') {
                targetPage = Math.min(totalPages, currentPage + 1);
            } else {
                targetPage = parseInt(page);
            }

            if (targetPage !== currentPage && targetPage >= 1 && targetPage <= totalPages) {
                const command = `/send 直播区跳转到第${targetPage}页 | /trigger`;
                if (typeof triggerSlash === 'function') {
                    triggerSlash(command);
                }
            }
