        // 创建漂浮装饰
        function createFloatingSymbols() {
            const symbols = ['☯', '卍', '☰', '☷', '☶', '☵', '☴', '☳', '☲', '☱'];
            const container = document.querySelector('.floating-symbols');

            for (let i = 0; i < 15; i++) {
                const symbol = document.createElement('div');
                symbol.className = 'symbol';
                symbol.textContent = symbols[Math.floor(Math.random() * symbols.length)];
                symbol.style.left = Math.random() * 100 + '%';
                symbol.style.animationDelay = Math.random() * 20 + 's';
                symbol.style.animationDuration = (20 + Math.random() * 10) + 's';
                container.appendChild(symbol);
            }
        }

        // 设置标签页监听
        function setupTabListeners() {
            document.querySelectorAll('.tab-btn').forEach(btn => {
                btn.addEventListener('click', function() {
                    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
                    this.classList.add('active');
                    currentTab = this.dataset.tab;
                    currentPage = 1;
                    loadProducts(currentTab, 1);
                });
            });
        }

        // 加载商品
        function loadProducts(category, page) {
            const grid = document.getElementById('products-grid');
            const products = productsData[category].items;

            // 生成当前页商品（每页都显示10个不同商品）
            grid.innerHTML = '';
            const startIdx = ((page - 1) * 10) % products.length;

            for (let i = 0; i < 10; i++) {
                const productIndex = (startIdx + i) % products.length;
                const product = products[productIndex];
                const multiplier = Math.floor(((page - 1) * 10 + i) / products.length) + 1;

                const card = document.createElement('div');
                card.className = 'product-card';
                card.innerHTML = `
                    <div class="product-name">${product.name}${multiplier > 1 ? ' · 改' + multiplier : ''}</div>
                    <div class="product-desc">${product.desc}</div>
                    <div class="product-price">
                        <span>💎</span>
                        <span>${product.price * multiplier} 积分</span>
                    </div>
                `;

                card.onclick = () => openPurchaseModal({
                    ...product,
                    name: product.name + (multiplier > 1 ? ' · 改' + multiplier : ''),
                    price: product.price * multiplier
                });

                grid.appendChild(card);
            }

            // 生成分页器
            generatePagination(category, page);
        }

        // 生成分页器
        function generatePagination(category, currentPage) {
            const pagination = document.getElementById('pagination');
            const totalPages = productsData[category].totalPages;

            pagination.innerHTML = '';

            // 首页按钮
            const firstBtn = createPageButton('首页', () => loadProducts(category, 1));
            firstBtn.disabled = currentPage === 1;
            pagination.appendChild(firstBtn);

            // 上一页按钮
            const prevBtn = createPageButton('上一页', () => loadProducts(category, currentPage - 1));
            prevBtn.disabled = currentPage === 1;
            pagination.appendChild(prevBtn);

            // 页码
            let startPage = Math.max(1, currentPage - 2);
            let endPage = Math.min(totalPages, startPage + 4);

            if (endPage - startPage < 4) {
                startPage = Math.max(1, endPage - 4);
            }

            for (let i = startPage; i <= endPage; i++) {
                const pageNum = document.createElement('span');
                pageNum.className = 'page-number' + (i === currentPage ? ' active' : '');
                pageNum.textContent = i;
                pageNum.onclick = () => {
                    currentPage = i;
                    loadProducts(category, i);
                };
                pagination.appendChild(pageNum);
            }

            if (endPage < totalPages) {
                const dots = document.createElement('span');
                dots.textContent = '...';
                dots.style.padding = '0 10px';
                pagination.appendChild(dots);
            }

            // 下一页按钮
            const nextBtn = createPageButton('下一页', () => loadProducts(category, currentPage + 1));
            nextBtn.disabled = currentPage === totalPages;
            pagination.appendChild(nextBtn);

            // 尾页按钮
            const lastBtn = createPageButton('尾页', () => loadProducts(category, totalPages));
            lastBtn.disabled = currentPage === totalPages;
            pagination.appendChild(lastBtn);
        }

        // 创建分页按钮
        function createPageButton(text, onClick) {
            const btn = document.createElement('button');
            btn.className = 'page-btn';
            btn.textContent = text;
            btn.onclick = onClick;
            return btn;
        }

        // 打开购买确认弹窗
        function openPurchaseModal(product) {
            selectedProduct = product;
            const modalInfo = document.getElementById('modal-product-info');
            modalInfo.innerHTML = `
                <div style="font-size: 24px; margin-bottom: 10px; color: var(--accent-gold);">${product.name}</div>
                <div style="margin-bottom: 10px; color: var(--text-secondary);">${product.desc}</div>
                <div style="font-size: 20px;">需要支付：<span style="color: var(--accent-gold);">💎 ${product.price} 积分</span></div>
                <div style="margin-top: 10px;">当前积分：<span style="color: var(--text-primary);">💎 ${userPoints}</span></div>
            `;
            document.getElementById('purchase-modal').classList.add('active');
        }

        // 关闭购买确认弹窗
        function closePurchaseModal() {
            document.getElementById('purchase-modal').classList.remove('active');
            selectedProduct = null;
        }

        // 确认购买
        function confirmPurchase() {
            if (selectedProduct && userPoints >= selectedProduct.price) {
                userPoints -= selectedProduct.price;
                document.getElementById('user-points').textContent = userPoints;

                // 使用 STscript 命令更新积分
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/echo severity=success 购买成功！您获得了 ${selectedProduct.name}`);
                }

                closePurchaseModal();
            } else {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/echo severity=error 积分不足，无法购买！`);
                }
                closePurchaseModal();
            }
        }
    </script>
