        // 播放视频
        function playVideo() {
            const message = '进入视频播放界面';
            const command = `/send ${message} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            }
        }

        // 提交评论
        function submitComment() {
            const input = document.getElementById('userCommentInput');
            const comment = input.value.trim();

            if (comment) {
                // 添加用户评论到列表顶部
                const commentsList = document.getElementById('commentsList');
                const newComment = document.createElement('div');
                newComment.className = 'comment-item user-comment';
                newComment.setAttribute('data-page', currentPage);
                newComment.innerHTML = `
                    <div class="comment-author">我的评论</div>
                    <div class="comment-text">${comment}</div>
                `;
                commentsList.insertBefore(newComment, commentsList.firstChild);

                // 清空输入框
                input.value = '';

                // 显示积分提示
                showPointsNotification();
            }
        }

        // 显示积分提示
        function showPointsNotification() {
            const notification = document.getElementById('pointsNotification');
            const points = Math.floor(Math.random() * 20) + 10; // 随机10-30积分
            document.getElementById('pointsValue').textContent = points;

            notification.classList.add('show');

            // 3秒后自动隐藏
            setTimeout(() => {
                notification.classList.remove('show');
            }, 3000);
        }

        // 分页功能
        function goToPage(page) {
            if (page === 'first') {
                currentPage = 1;
            } else if (page === 'prev') {
                if (currentPage > 1) currentPage--;
            } else if (page === 'next') {
                if (currentPage < totalPages) currentPage++;
            } else if (page === 'last') {
                currentPage = totalPages;
            } else if (typeof page === 'number') {
                currentPage = page;
            }

            updatePagination();
            // 这里可以添加加载新评论的逻辑
            console.log(`切换到第${currentPage}页`);
        }

        // 更新分页显示
        function updatePagination() {
            const pageNumbers = document.querySelectorAll('.page-number');
            pageNumbers.forEach(num => {
                num.classList.remove('active');
                if (parseInt(num.textContent) === currentPage) {
                    num.classList.add('active');
                }
            });
        }
    </script>
