            <button class="back-button" onclick="backToPost()">← 返回原帖</button>
        </div>

        <!-- 视频播放区域 -->
        <div class="video-screen">
            <div class="video-content" id="video-content">$3</div>
        </div>

        <!-- 视频控制条 -->
        <div class="video-controls">
            <button class="play-pause-btn" id="playPauseBtn" onclick="togglePlayPause()">▶</button>
            <div class="progress-bar" onclick="seekVideo(event)">
                <div class="progress-fill" id="progressFill"></div>
            </div>
            <div class="time-display" id="timeDisplay">00:00 / 00:00</div>
        </div>

        <!-- 器官状态面板 -->
        <div class="organ-status-panel">
            <div class="status-title">〖 实时器官状态监测 〗</div>
            <div class="status-content">$4</div>
        </div>
    </div>

    <script>
        let isPlaying = false;
        let currentTime = 0;
        let duration = 300; // 5分钟视频
        let progressInterval;

        // 播放/暂停切换
        function togglePlayPause() {
            const btn = document.getElementById('playPauseBtn');
            const progressFill = document.getElementById('progressFill');

            if (isPlaying) {
                // 暂停
                isPlaying = false;
                btn.textContent = '▶';
                clearInterval(progressInterval);
            } else {
                // 播放
                isPlaying = true;
                btn.textContent = '❚❚';

                progressInterval = setInterval(() => {
                    if (currentTime < duration) {
                        currentTime += 0.1;
                        updateProgress();

                        // 模拟内容滚动
                        const content = document.getElementById('video-content');
                        if (content.scrollTop < content.scrollHeight - content.clientHeight) {
                            content.scrollTop += 0.5;
                        }
                    } else {
                        // 视频结束
                        isPlaying = false;
                        btn.textContent = '▶';
                        clearInterval(progressInterval);
                        currentTime = 0;
                        updateProgress();
                    }
                }, 100);
            }
        }

        // 更新进度条
        function updateProgress() {
            const progressFill = document.getElementById('progressFill');
            const timeDisplay = document.getElementById('timeDisplay');

            const percentage = (currentTime / duration) * 100;
            progressFill.style.width = percentage + '%';

            const currentMinutes = Math.floor(currentTime / 60);
            const currentSeconds = Math.floor(currentTime % 60);
            const durationMinutes = Math.floor(duration / 60);
            const durationSeconds = Math.floor(duration % 60);

            timeDisplay.textContent =
                `${String(currentMinutes).padStart(2, '0')}:${String(currentSeconds).padStart(2, '0')} / ` +
                `${String(durationMinutes).padStart(2, '0')}:${String(durationSeconds).padStart(2, '0')}`;
        }

        // 点击进度条跳转
        function seekVideo(event) {
            const progressBar = event.currentTarget;
            const rect = progressBar.getBoundingClientRect();
            const clickX = event.clientX - rect.left;
            const percentage = clickX / rect.width;

            currentTime = percentage * duration;
            updateProgress();

            // 调整内容滚动位置
            const content = document.getElementById('video-content');
            const maxScroll = content.scrollHeight - content.clientHeight;
            content.scrollTop = maxScroll * percentage;
        }

        // 返回原帖子
        function backToPost() {
            const command = `/send 返回原帖子 | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            } else {
                alert('返回功能需要在SillyTavern环境中使用');
            }
        }

        // 初始化
        window.addEventListener('load', () => {
            updateProgress();
        });
    </script>
</body>
</html>
